有个问题啊，为什么这个 getfail() 要在没有儿子的时候把 ch[u][i] 连到 ch[fail[u]][i] 上面
void getfail()
{
	queue<int> q;
	for (int i = 0; i < 26; ++i)
	{
		if (ch[0][i])
			q.push(ch[0][i]);
	}
	for (int u; q.size();)
	{
		u = q.front();
		q.pop();
		for (int i = 0; i < 26; ++i)
		{
			if (ch[u][i])
			{
				fail[ch[u][i]] = ch[fail[u]][i];
				q.push(ch[u][i]);
			}
			else
				ch[u][i] = ch[fail[u]][i];
		}
	}
}

